import sqlite3
import pandas as pd
import numpy as np
from scipy import stats
from statsmodels.stats.multitest import multipletests

def run_full_analysis():
    try:
        # 1. Database connection and data loading
        conn = sqlite3.connect('dacomp-080.sqlite')
        df = pd.read_sql("""
            SELECT duration_in_seconds, survey_progress, 
                   distribution_channel, email_domain, user_language
            FROM qualtrics__response
            WHERE email_domain IS NOT NULL
        """, conn)
        conn.close()

        # 2. Data validation and cleaning
        # Remove rows with invalid duration values
        df = df[df['duration_in_seconds'] > 0]

        # Get global parameters
        global_duration = df['duration_in_seconds'].describe()
        global_progress = df['survey_progress'].describe()
        global_median_duration = df['duration_in_seconds'].median()

        # 3. Hypothesis testing function with robust numerical handling
        def test_subset(subset_df, global_duration, global_progress, global_median_duration):
            results = {}

            # H1: Means equal (Welch's t-test with validation)
            global_mean = global_duration['mean']
            if len(subset_df) < 2:
                results['H1'] = {'statistic': np.nan, 'pvalue': np.nan, 'effect_size': np.nan, 'n': len(subset_df)}
            else:
                try:
                    # Calculate pooled std with validation
                    subset_std = subset_df['duration_in_seconds'].std()
                    global_std = global_duration['std()]
                    pooled_std = np.sqrt((subset_std**2 + global_std**2)/2)
                    cohen_d = (subset_df['duration_in_seconds'].mean() - global_mean) / pooled_std

                    # Welch's t-test
                    t_stat, p_val = stats.ttest_ind(
                        subset_df['duration_in_seconds'],
                        pd.Series([global_mean]*len(subset_df)),
                        equal_var=False
                    )
                    results['H1'] = {
                        'statistic': t_stat, 'pvalue': p_val, 'effect_size': cohen_d,
                        'n': len(subset_df)
                    }
                except:
                    results['H1'] = {'statistic': np.nan, 'pvalue': np.nan, 'effect_size': np.nan, 'n': len(subset_df)}

            # H2: Variances equal (Levene's test)
            if len(subset_df) >= 2:
                try:
                    _, p_val = stats.levene(subset_df['duration_in_seconds'], 
                                          pd.Series([global_duration['std']]*len(subset_df)))
                    results['H2'] = {
                        'statistic': np.nan, 'pvalue': p_val, 'effect_size': np.nan
                    }
                except:
                    results['H2'] = {'statistic': np.nan, 'pvalue': np.nan, 'effect_size': np.nan}
            else:
                results['H2'] = {'statistic': np.nan, 'pvalue': np.nan, 'effect_size': np.nan}

            # H3: Distribution matches (KS test)
            try:
                _, p_val = stats.kstest(subset_df['duration_in_seconds'], 
                                      'norm', args=(global_duration['mean'], global_duration['std']))
                results['H3'] = {
                    'statistic': np.nan, 'pvalue': p_val, 'effect_size': np.nan
                }
            except:
                results['H3'] = {'statistic': np.nan, 'pvalue': np.nan, 'effect_size': np.nan}

            # H4: Progress independent of channel (Chi-square)
            try:
                contingency = pd.crosstab(subset_df['survey_progress'] > global_progress['median'],
                                         subset_df['distribution_channel'])
                if contingency.size > 0:
                    _, p_val, _, _ = stats.chi2_contingency(contingency)
                    results['H4'] = {
                        'statistic': np.nan, 'pvalue': p_val, 'effect_size': np.nan
                    }
                else:
                    results['H4'] = {'statistic': np.nan, 'pvalue': np.nan, 'effect_size': np.nan}
            except:
                results['H4'] = {'statistic': np.nan, 'pvalue': np.nan, 'effect_size': np.nan}

            # H5: Median equals global median (Wilcoxon)
            try:
                if len(subset_df) >= 3:
                    _, p_val = stats.wilcoxon(subset_df['duration_in_seconds'], 
                                             [global_median_duration]*len(subset_df))
                    cohen_h = (subset_df['duration_in_seconds'].median() - global_median_duration) / global_duration['std']
                    results['H5'] = {
                        'statistic': np.nan, 'pvalue': p_val, 'effect_size': cohen_h
                    }
                else:
                    results['H5'] = {'statistic': np.nan, 'pvalue': np.nan, 'effect_size': np.nan}
            except:
                results['H5'] = {'statistic': np.nan, 'pvalue': np.nan, 'effect_size': np.nan}

            return results

        # 4. Group by subsets and run tests
        grouped = df.groupby(['distribution_channel', 'email_domain', 'user_language'])
        results_list = []

        for name, subset_df in grouped:
            results = test_subset(subset_df, global_duration, global_progress, global_median_duration)
            results['subset'] = name
            results_list.append(results)

        # 5. Combine and save results
        results_df = pd.json_normalize(results_list)
        results_df.to_csv('hypothesis_test_results.csv', index=False)

        # 6. Generate summary statistics
        pvals_below_005 = (results_df[['H1 pvalue', 'H2 pvalue', 'H3 pvalue', 
                                    'H4 pvalue', 'H5 pvalue']] < 0.05).any(axis=1)
        print(f"\nSubsets with p < 0.05: {len(pvals_below_005)}")
        print(f"Subsets with small samples (n < 20): {len(results_df[results_df['n'] < 20])}")
        print(f"Average effect size (Cohen's d) for significant H1: {results_df.loc[pvals_below_005, 'H1 effect_size'].mean():.3f}")
        print("\nDistribution of p-values across all tests:")
        print(results_df[['H1 pvalue', 'H2 pvalue', 'H3 pvalue', 
                        'H4 pvalue', 'H5 pvalue']].describe())

        return True

    except Exception as e:
        print(f"Error in analysis: {str(e)}")
        return False

# Execute the full analysis
run_full_analysis()

